java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(1, 1, java.awt.image.BufferedImage.TYPE_INT_RGB);
java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
javax.imageio.ImageIO.write(img, "jpg", baos);

java.util.Iterator<javax.imageio.ImageReader> readers = javax.imageio.ImageIO.getImageReadersByFormatName("jpg");
assert readers.hasNext() : "No JPEG reader found";
javax.imageio.ImageReader reader = readers.next();

net.coobird.thumbnailator.util.exif.Orientation orientation = null;
boolean npeCaught = false;

try (javax.imageio.stream.ImageInputStream iis = javax.imageio.ImageIO.createImageInputStream(new java.io.ByteArrayInputStream(baos.toByteArray()))) {
    reader.setInput(iis);
    try {
        orientation = net.coobird.thumbnailator.util.exif.ExifUtils.getExifOrientation(reader, 0);
    } catch (NullPointerException e) {
        // Expected undocumented NPE caused by missing metadata in the generated JPEG
        npeCaught = true;
    }
} finally {
    reader.dispose();
}

assert npeCaught || orientation == null : "Expected NPE or null for image without EXIF metadata";
System.out.println("__CHECK__ getExifOrientation " + (npeCaught ? "NPE_CAUGHT" : orientation));

